import{_ as r,C as t,o as a,c as n,a3 as s,b as d,w as o,a as l,E as c,a2 as u}from"./chunks/framework.rPoJfhSN.js";const C=JSON.parse('{"title":"ADR-001: database.sql frente a seeders","description":"","frontmatter":{},"headers":[],"relativePath":"decisiones/001-sql-vs-seeders.md","filePath":"decisiones/001-sql-vs-seeders.md","lastUpdated":null}'),m={name:"decisiones/001-sql-vs-seeders.md"};function p(h,e,b,f,_,g){const i=t("Mermaid");return a(),n("div",null,[e[1]||(e[1]=s('<h1 id="adr-001-database-sql-frente-a-seeders" tabindex="-1">ADR-001: <code>database.sql</code> frente a seeders <a class="header-anchor" href="#adr-001-database-sql-frente-a-seeders" aria-label="Permalink to &quot;ADR-001: `database.sql` frente a seeders&quot;">​</a></h1><ul><li><strong>Estado:</strong> aceptada para la distribución actual</li><li><strong>Decisión:</strong> usar <code>database/database.sql</code> para reproducir la demostración; reservar migraciones y seeders para desarrollo limpio y pruebas.</li></ul><h2 id="contexto" tabindex="-1">Contexto <a class="header-anchor" href="#contexto" aria-label="Permalink to &quot;Contexto&quot;">​</a></h2><p>El snapshot SQL contiene un conjunto coherente de catálogo, tiendas, contenido, ajustes y referencias de archivos. <code>DatabaseSeeder</code> ejecuta únicamente un subconjunto de seeders y no reconstruye la misma experiencia.</p><p>Algunos seeders de demostración dependen de identificadores preexistentes, usan valores rígidos o pueden generar slugs y SKU repetidos. Ejecutarlos después del snapshot también puede provocar colisiones.</p><h2 id="decision" tabindex="-1">Decisión <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decisión&quot;">​</a></h2>',6)),(a(),d(u,null,{default:o(()=>[c(i,{id:"mermaid-27",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20N%7B%C2%BFQu%C3%A9%20necesitas%3F%7D%0A%20%20%20%20N%20--%3E%7CDemo%20fiel%20o%20evaluaci%C3%B3n%7C%20SQL%5BImportar%20database%2Fdatabase.sql%5D%0A%20%20%20%20N%20--%3E%7CPruebas%20automatizadas%7C%20TEST%5BMigrar%20una%20base%20aislada%5D%0A%20%20%20%20N%20--%3E%7CInstalaci%C3%B3n%20limpia%7C%20SEED%5BMigrar%20y%20sembrar%5D%0A%20%20%20%20SEED%20--%3E%20GAP%5BCompletar%20seeders%20faltantes%5D%0A%20%20%20%20SQL%20--%3E%20CLEAR%5BRotar%20credenciales%20y%20limpiar%20cach%C3%A9s%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="consecuencias" tabindex="-1">Consecuencias <a class="header-anchor" href="#consecuencias" aria-label="Permalink to &quot;Consecuencias&quot;">​</a></h2><h3 id="positivas" tabindex="-1">Positivas <a class="header-anchor" href="#positivas" aria-label="Permalink to &quot;Positivas&quot;">​</a></h3><ul><li>La demostración se levanta con contenido y relaciones congruentes.</li><li>Se reduce el tiempo para evaluación funcional.</li><li>Los tests pueden seguir usando un estado efímero por migraciones.</li></ul><h3 id="costos-y-riesgos" tabindex="-1">Costos y riesgos <a class="header-anchor" href="#costos-y-riesgos" aria-label="Permalink to &quot;Costos y riesgos&quot;">​</a></h3><ul><li>El SQL es una fotografía y puede divergir de futuras migraciones.</li><li>Puede contener caché, referencias de archivos y datos de demostración obsoletos.</li><li>No es adecuado como estrategia repetible para múltiples instalaciones sin sanitización.</li></ul><h2 id="procedimiento" tabindex="-1">Procedimiento <a class="header-anchor" href="#procedimiento" aria-label="Permalink to &quot;Procedimiento&quot;">​</a></h2><p>Para una demo nueva: crea <code>plazora</code>, importa el SQL, restaura los archivos asociados, rota todas las credenciales, revisa ajustes y ejecuta <code>php artisan optimize:clear</code>.</p><p>No ejecutes seeders encima del snapshot. En releases posteriores usa migraciones incrementales.</p><h2 id="camino-de-mejora" tabindex="-1">Camino de mejora <a class="header-anchor" href="#camino-de-mejora" aria-label="Permalink to &quot;Camino de mejora&quot;">​</a></h2><ol><li>Crear factories deterministas para usuarios, tiendas y catálogo.</li><li>Eliminar dependencias de IDs rígidos.</li><li>Hacer los seeders idempotentes o documentar que sólo operan en base vacía.</li><li>Añadir un seeder explícito de demo y otro mínimo de producción.</li><li>Probar que <code>migrate:fresh --seed</code> produce un sistema utilizable.</li><li>Generar snapshots sanitizados desde ese flujo y retirar el SQL manual cuando exista paridad.</li></ol>',10))])}const v=r(m,[["render",p]]);export{C as __pageData,v as default};
